Ui.Script:
-- ── The four font-PATH globals (ref Fonts.xml l.4-7) ────────────────────────────────── -- This file quoted the reference's colour block (l.8-19) and skipped the four lines above -- it. `STANDARD_TEXT_FONT` is the one that matters: **68 corpus addons name it**, and per -- 1207's rule that number is read rather than quoted — 64 of them are copies of -- `Dewdrop-2.0.lua` and only 4 are addon code. But Dewdrop is *the* Ace2 menu library, and -- it calls `button.text:SetFont(STANDARD_TEXT_FONT, height)` **unguarded** at two of its -- three sites (l.207 and l.496; only l.2294 writes `STANDARD_TEXT_FONT or "Fonts\\..."`), -- so a nil global is a failed SetFont on every menu button the Ace2 ecosystem draws. -- -- The other three come with it because they are the same four-line block and cost nothing: -- UNIT_NAME_FONT (0 corpus addons), DAMAGE_TEXT_FONT (1), NAMEPLATE_FONT (1). All four are -- the same face in 1.12 — the reference assigns FRIZQT__ to every one — and that identity -- is the reference's, not a simplification of ours. STANDARD_TEXT_FONT = "Fonts\\FRIZQT__.TTF" -- ref Fonts.xml l.4 UNIT_NAME_FONT = "Fonts\\FRIZQT__.TTF" -- l.5 DAMAGE_TEXT_FONT = "Fonts\\FRIZQT__.TTF" -- l.6 NAMEPLATE_FONT = "Fonts\\FRIZQT__.TTF" -- l.7 NORMAL_FONT_COLOR_CODE = "|cffffd200" -- ref Fonts.xml l.8 HIGHLIGHT_FONT_COLOR_CODE = "|cffffffff" -- l.9 RED_FONT_COLOR_CODE = "|cffff2020" -- l.10 GREEN_FONT_COLOR_CODE = "|cff20ff20" -- l.11 GRAY_FONT_COLOR_CODE = "|cff808080" -- l.12 -- l.13, and it was the ONE line of this block that was missing — the comments beside it -- even skipped from `l.12` to `l.14`. `aux-addon.lua:7` concatenates it at file scope -- (`LIGHTYELLOW_FONT_COLOR_CODE .. "aux: " ..`), so its absence was not a wrong colour, it -- was the addon dying on its own first line. LIGHTYELLOW_FONT_COLOR_CODE = "|cffffff9a" -- l.13 FONT_COLOR_CODE_CLOSE = "|r" -- l.14 NORMAL_FONT_COLOR = { r = 1.0, g = 0.82, b = 0 } -- l.15 HIGHLIGHT_FONT_COLOR = { r = 1.0, g = 1.0, b = 1.0 } -- l.16 GRAY_FONT_COLOR = { r = 0.5, g = 0.5, b = 0.5 } -- l.17 GREEN_FONT_COLOR = { r = 0.1, g = 1.0, b = 0.1 } -- l.18 RED_FONT_COLOR = { r = 1.0, g = 0.1, b = 0.1 } -- l.19 -- Added this session (decision 0216 §8, the spellbook slice) — the ref's own l.20, the -- one color this file was missing: a passive spell's name text (SpellBookFrame.lua:385). PASSIVE_SPELL_FONT_COLOR = { r = 0.77, g = 0.64, b = 0 } -- l.20
-- The item-quality palette — **built from the engine verb, exactly as the reference -- builds it** (ref UIParent.lua l.65-72, verbatim shape; decision 1199): -- -- ITEM_QUALITY_COLORS = { } -- for i = -1, 6 do … = GetItemQualityColor(i) end -- -- It used to be seven hand-typed rows here. They were CLOSE and not exact — 0.62 where -- the client's byte is 0x9d/255 = 0.6157, 0.64/0.21/0.93 where Epic is -- 0xa3/0x35/0xee — and they carried no `.hex`, which the reference's table has and -- which addons splice straight into a chat link. `GetItemQualityColor` is now a real -- engine binding over wow-5875-re RF-0055's byte-verified table, so the rounding and -- the second source both go. -- -- The loop starts at -1 like the reference's: `UIParent.lua` reads one index before the -- array there, and our binding answers Poor for it rather than reproducing that. ITEM_QUALITY_COLORS = { } for i = -1, 6 do ITEM_QUALITY_COLORS[i] = { } ITEM_QUALITY_COLORS[i].r, ITEM_QUALITY_COLORS[i].g, ITEM_QUALITY_COLORS[i].b, ITEM_QUALITY_COLORS[i].hex = GetItemQualityColor(i) end
-- ── RAID_CLASS_COLORS (spec: ref Fonts.xml l.43-53 — same name, same nine keys, same -- channel values; our own way of writing them down) ─────────────────────────────────── -- -- The per-class colour every raid/party addon paints names with. **22 corpus addons** reach -- it — nine of them through `Babble-Class-2.0`, but seven more by hand (KLHThreatMeter, -- CT_RaidAssist, CT_ExpenseHistory, _LazyPig, FuBar_oRA2CooldownFu, and BigWigs in two -- plugins) — and absent it is `bad argument #1 to 'pairs' (table expected, got nil)` at -- file scope. That was the whole of the harness's remaining `table expected` row: three -- addons, one missing table, found by asking the blocker table which addons were behind it. -- -- Written as the eight distinct triples plus a loop that lifts them into the `{r=,g=,b=}` -- records addons index (`RAID_CLASS_COLORS["HUNTER"].r`), the same spec-plus-builder shape -- ITEM_QUALITY_COLORS above takes. The only thing worth SAYING about a palette is which -- colours are in it, and a bare triple says that with no ceremony; the record shape is the -- addon-facing contract and belongs in the one line that builds it. -- -- EIGHT triples for nine classes, and that is the 1.12 client's own doing: shamans have no -- colour of their own. They were Horde-only and paladins Alliance-only, so the two never -- shared a raid frame and the client hands SHAMAN the paladin pink. We ASSIGN it, which -- states the fact instead of re-typing three numbers and asking the next reader to believe -- a comment. (`ROGUE`'s yellow likewise reconciles with nothing else in the client. A later -- client's palette is not this one's; these are 1.12's.) Each class still gets its OWN -- record below, so an addon that writes to `.PALADIN.r` does not move SHAMAN — the -- reference's two equal-but-separate tables, preserved. local classRGB = { WARRIOR = { 0.78, 0.61, 0.43 }, PALADIN = { 0.96, 0.55, 0.73 }, HUNTER = { 0.67, 0.83, 0.45 }, ROGUE = { 1.0, 0.96, 0.41 }, PRIEST = { 1.0, 1.0, 1.0 }, MAGE = { 0.41, 0.8, 0.94 }, WARLOCK = { 0.58, 0.51, 0.79 }, DRUID = { 1.0, 0.49, 0.04 }, } classRGB.SHAMAN = classRGB.PALADIN RAID_CLASS_COLORS = {} for token, rgb in pairs(classRGB) do RAID_CLASS_COLORS[token] = { r = rgb[1], g = rgb[2], b = rgb[3] } end -- CHAT_FONT_HEIGHTS — the chat window's four selectable font heights, the reference's own -- table verbatim (ref Fonts.xml l.21-26). It sat in the note below as "costs nine lines the -- day something reads it" until decision 1589 (B246) built the chat tab's **Font Size** -- submenu, which is the reference's only reader too (`FCFOptionsDropDown_Initialize` -- iterates it). Still zero corpus addons, so the demand here is ours, not theirs. CHAT_FONT_HEIGHTS = { 12, 14, 16, 18 }
-- The page ink and the title ink per readable-material, ref Fonts.xml l.27-42 verbatim. -- -- These were deliberately absent for a long time — "zero corpus addons name either, and -- nothing benilla ships reads them; they cost nine lines each the day something does". -- 1751's ninth window is that day: the reference's own `GetMaterialTextColors` -- (UIParent.lua l.1880-1888) reads them by these names, and it is what the sourced -- `ItemTextFrame.xml` calls. Our ItemTextFrame carried a private -- `BENILLA_MATERIAL_*_COLOR_TABLE` pair; both are deleted, and this is where 1.12 keeps -- the one that remains. MATERIAL_TEXT_COLOR_TABLE = { ["Default"] = {0.18, 0.12, 0.06}, ["Stone"] = {1.0, 1.0, 1.0}, ["Parchment"] = {0.18, 0.12, 0.06}, ["Marble"] = {0, 0, 0}, ["Silver"] = {0.12, 0.12, 0.12}, ["Bronze"] = {0.18, 0.12, 0.06}, } MATERIAL_TITLETEXT_COLOR_TABLE = { ["Default"] = {0, 0, 0}, ["Stone"] = {0.93, 0.82, 0}, ["Parchment"] = {0, 0, 0}, ["Marble"] = {0.93, 0.82, 0}, ["Silver"] = {0.93, 0.82, 0}, ["Bronze"] = {0.93, 0.82, 0}, }
